(5590713, 810225, 59415, '<td valign="top">I like the crop on this shot.  The color tones don''t work together as well as they could.  I think it would be cool if you could do that shot with some color in the background from a colored sky or some other means.</td>', 'I like the crop on this shot.  The color tones don''t work together as well as they could.  I think it would be cool if you could do that shot with some color in the background from a colored sky or some other means.', '2009-07-29 16:50:23.000000', NULL, 1),
(5590715, 809212, 59415, '<td valign="top">The background is very interesting in this photo.</td>', 'The background is very interesting in this photo.', '2009-07-29 16:50:41.000000', NULL, 1),
(5590716, 810233, 59415, '<td valign="top">I like the tones in this shot, but the cross could be tweaked to be straiter in the crop.  That would make it a better composition in my opinion.</td>', 'I like the tones in this shot, but the cross could be tweaked to be straiter in the crop.  That would make it a better composition in my opinion.', '2009-07-29 16:51:21.000000', NULL, 1),
