(5590725, 810006, 59415, '<td valign="top">He looks too good for McD''s.  He might be made for the super market.  Great tones on this shot.  The tag in the ear really does the trick for the challenge.</td>', 'He looks too good for McD''s.  He might be made for the super market.  Great tones on this shot.  The tag in the ear really does the trick for the challenge.', '2009-07-29 16:56:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5590728, 809713, 59415, '<td valign="top">This is one of those shots that is so hard to get because of all the vertical lines.  That center stone looks crooked, but there is little or nothing that you could do about it.</td>', 'This is one of those shots that is so hard to get because of all the vertical lines.  That center stone looks crooked, but there is little or nothing that you could do about it.', '2009-07-29 16:58:11.000000', NULL, 1),
