(5592428, 809052, 57447, '<td valign="top">Nice work, should do very well!</td>', 'Nice work, should do very well!', '2009-07-31 09:41:23.000000', NULL, 1),
(5592469, 810035, 99710, '<td valign="top">really, i don''t get it....</td>', 'really, i don''t get it....', '2009-07-31 10:37:55.000000', NULL, 1),
