(5593295, 809510, 50034, '<td valign="top">"Hand-Over-My-Heart" THANKS for the sacrifice of your Loved Ones!  Freedom must be always cherished, and I DO.  :)</td>', '"Hand-Over-My-Heart" THANKS for the sacrifice of your Loved Ones!  Freedom must be always cherished, and I DO.  :)', '2009-08-01 02:27:58.000000', NULL, 1),
(5593298, 809999, 50034, '<td valign="top">Excellent Rendering of the Theme!  :)</td>', 'Excellent Rendering of the Theme!  :)', '2009-08-01 02:28:53.000000', NULL, 1),
(5593776, 810219, 99767, '<td valign="top">Super cool shot.</td>', 'Super cool shot.', '2009-08-01 13:17:27.000000', NULL, 1),
(5594062, 810113, 99448, '<td valign="top">wow, i love the the thickness of the dead flower and the colours are great,</td>', 'wow, i love the the thickness of the dead flower and the colours are great,', '2009-08-01 17:51:39.000000', NULL, 1),
(5594209, 810157, 3087, '<td valign="top">Great capture, beautiful detail, great composition, clean background... in many ways a perfect capture ... and yet it doesn''t thrill me in the way some bird photography does. Perhaps it''s that black background, maybe there''s part of me that feels more lifted when I see a more natural environmental backdrop that places the bird in context? I''m not sure. On the other hand, it''s an image I''d be pleased as punch with, had I taken it myself!</td>', 'Great capture, beautiful detail, great composition, clean background... in many ways a perfect capture ... and yet it doesn''t thrill me in the way some bird photography does. Perhaps it''s that black background, maybe there''s part of me that feels more lifted when I see a more natural environmental backdrop that places the bird in context? I''m not sure. On the other hand, it''s an image I''d be pleased as punch with, had I taken it myself!', '2009-08-01 19:27:49.000000', NULL, 1),
(5594216, 809225, 3087, '<td valign="top">A great image, the large areas of shadow and the black suit are a great foil to the sunlit face and hand. Not a particularly strong link to the theme, for me.</td>', 'A great image, the large areas of shadow and the black suit are a great foil to the sunlit face and hand. Not a particularly strong link to the theme, for me.', '2009-08-01 19:30:32.000000', NULL, 1),
(5594218, 810220, 3087, '<td valign="top">cute!</td>', 'cute!', '2009-08-01 19:30:52.000000', NULL, 1),
(5595346, 809888, 52549, '<td valign="top">Definitely in my top 3. Great shot and good luck.</td>', 'Definitely in my top 3. Great shot and good luck.', '2009-08-02 15:09:13.000000', NULL, 1),
(5595348, 809999, 52549, '<td valign="top">Fascinating crop. Good take on the challenge.</td>', 'Fascinating crop. Good take on the challenge.', '2009-08-02 15:10:59.000000', NULL, 1),
(5595349, 810219, 52549, '<td valign="top">Cool shot.</td>', 'Cool shot.', '2009-08-02 15:11:34.000000', NULL, 1),
