(5598588, 809889, 108642, '<td valign="top">Wow, very moving.</td>', 'Wow, very moving.', '2009-08-04 16:52:37.000000', NULL, 1),
(5598847, 810006, 2158, '<td valign="top">I really like this a lot.  Without the title, however, it really doesn''t belong in this challenge.</td>', 'I really like this a lot.  Without the title, however, it really doesn''t belong in this challenge.', '2009-08-04 21:24:37.000000', NULL, 1),
